mapper.select:
SELECT model_id FROM bt_ai_model
WHERE status_cd = '00A'
  AND model_type = 'llm'
  AND space_id = #{spaceId}
  AND bot_id = #{botId}
  AND creator_id = #{userId}
 1

SELECT variable_code, variable_value
FROM bt_ai_env_variable
WHERE status_cd = '00A'
  AND space_id = #{spaceId}
  AND bot_id = #{botId}
  AND creator_id = #{userId}

SELECT a.mcp_id
FROM bt_ai_mcp a
JOIN bt_mcp_server b ON b.server_id = a.mcp_id
WHERE a.status_cd = '00A'
  AND a.space_id = #{spaceId}
  AND a.bot_id = #{botId}
  AND a.creator_id = #{userId}
  AND b.status_cd = '00A'


    AND b.tenant_id = -1


    AND b.tenant_id = a.space_id

SELECT a.skill_id
FROM bt_ai_skill a
JOIN bt_agent_skill b ON b.skill_id = a.skill_id
WHERE a.status_cd = '00A'
  AND a.space_id = #{spaceId}
  AND a.bot_id = #{botId}
  AND a.creator_id = #{userId}
  AND b.status_cd = '00A'


    AND b.tenant_id = -1


    AND b.tenant_id = a.space_id

SELECT file_content FROM bt_ai_workspace
WHERE status_cd = '00A'
  AND space_id = #{spaceId}
  AND bot_id = #{botId}
  AND creator_id = #{userId}
  AND file_name = #{fileName}
 1

SELECT file_name, file_content
FROM bt_ai_workspace
WHERE status_cd = '00A'
  AND space_id = #{spaceId}
  AND bot_id = #{botId}
  AND creator_id = #{userId}
  AND #{botId} = -1
  AND (memory_type IS NULL OR memory_type = '')
